// M0.5 SPIKE — test media fixture resolution.
//
// Media files are generated by scripts/generate-test-media.sh into
// tests/fixtures/media/ (gitignored). All content is synthesized
// (ffmpeg testsrc2 + sine) and license-clean.

use crate::error::TideError;
use std::path::{Path, PathBuf};

/// Resolves the fixtures/media directory relative to the workspace.
///
/// The spike runs from `src-tauri` (dev) or the installed binary; the
/// script output location is the repo-relative fixtures path.
pub fn media_dir() -> Result<PathBuf, TideError> {
    // dev: <repo>/tests/fixtures/media ; repo root is two levels above
    // the manifest dir.
    let manifest_dir = env!("CARGO_MANIFEST_DIR");
    let candidate = Path::new(manifest_dir)
        .join("..")
        .join("tests")
        .join("fixtures")
        .join("media");
    let candidate = candidate.canonicalize().map_err(|_| {
        TideError::NotFound(format!(
            "media fixtures not found at {} — run scripts/generate-test-media.sh",
            candidate.display()
        ))
    })?;
    Ok(candidate)
}

pub fn content_type_for(path: &Path) -> &'static str {
    match path
        .extension()
        .and_then(|e| e.to_str())
        .map(|e| e.to_ascii_lowercase())
        .as_deref()
    {
        Some("mp4") | Some("m4v") => "video/mp4",
        Some("webm") => "video/webm",
        Some("mkv") => "video/x-matroska",
        Some("srt") => "text/plain; charset=utf-8",
        Some("jpg") | Some("jpeg") => "image/jpeg",
        Some("bin") => "application/octet-stream",
        _ => "application/octet-stream",
    }
}

/// Content type for a bare file name (no directory context).
pub fn content_type_of_name(name: &str) -> &'static str {
    content_type_for(Path::new(name))
}

/// Lists media fixtures (name, byte size, content type), sorted by name.
pub fn list_media() -> Result<Vec<MediaFixture>, TideError> {
    let dir = media_dir()?;
    let mut out = Vec::new();
    for entry in std::fs::read_dir(&dir)? {
        let entry = entry?;
        let path = entry.path();
        if !path.is_file() {
            continue;
        }
        let name = entry.file_name().to_string_lossy().to_string();
        let size = entry.metadata().map(|m| m.len()).unwrap_or(0);
        out.push(MediaFixture {
            name,
            size,
            content_type: content_type_for(&path).to_string(),
        });
    }
    out.sort_by(|a, b| a.name.cmp(&b.name));
    Ok(out)
}

/// Resolves a fixture file by name, refusing anything that escapes the
/// media directory (the fixture server only ever serves this directory).
pub fn resolve_media_file(name: &str) -> Result<PathBuf, TideError> {
    if name.contains('\\')
        || name.contains('/')
        || name.contains("..")
        || name.contains(':')
        || name.is_empty()
    {
        return Err(TideError::InvalidInput("invalid media fixture name".into()));
    }
    let path = media_dir()?.join(name);
    if !path.is_file() {
        return Err(TideError::NotFound(format!(
            "media fixture not found: {name}"
        )));
    }
    Ok(path)
}

#[derive(Debug, Clone, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct MediaFixture {
    pub name: String,
    pub size: u64,
    pub content_type: String,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn content_types_are_sensible() {
        assert_eq!(content_type_for(Path::new("a.mp4")), "video/mp4");
        assert_eq!(content_type_for(Path::new("a.WEBM")), "video/webm");
        assert_eq!(content_type_for(Path::new("a.mkv")), "video/x-matroska");
        assert_eq!(
            content_type_for(Path::new("a.xyz")),
            "application/octet-stream"
        );
    }

    #[test]
    fn resolve_rejects_path_escape() {
        assert!(resolve_media_file("../secret.txt").is_err());
        assert!(resolve_media_file("a\\b.mp4").is_err());
        assert!(resolve_media_file("C:boot").is_err());
        assert!(resolve_media_file("").is_err());
    }

    #[test]
    fn media_dir_exists_when_fixtures_generated() {
        // Guards the LOCAL fixture setup: the media files are
        // generated by scripts/generate-test-media.sh into a
        // gitignored directory, so environments that never ran the
        // script (CI) legitimately lack them — SKIP, don't fail. Run
        // the script locally to exercise this assertion.
        match media_dir() {
            Ok(dir) => assert!(dir.is_dir()),
            Err(TideError::NotFound(_)) => {
                eprintln!("skip: media fixtures not generated (run scripts/generate-test-media.sh locally)");
            }
            Err(other) => panic!("unexpected error: {other}"),
        }
    }
}
